const CELL = new Set(['map', 'province', 'provinces', 'people', 'person', 'history', 'world', 'country', 'news', 'institutions', 'parties', 'parliament', 'justice', 'treaties', 'diplomacy', 'wars', 'my_secrets', 'dossiers', 'debts', 'contracts', 'my_companies', 'informants']);
