  return `${o.name}, ${countryProvinces(w, o.id).length} provinces. Directions and distances are from its capital${cap ? ` ${cap.name}` : ''}.\n${countryProvinces(w, o.id).sort((a, b) => (dist[a.id] ?? 99) - (dist[b.id] ?? 99)).map(line).join('\n')}${own ? '' : `\nWhat troops stand where is not on any map; borders shows what is seen along your own frontier, and province:<id> what is known of one place.${staffSeat ? ` ${serviceWord(intel)}` : ''}`}`;
