// What others can know of someone's health: a wound or grave illness shows, and so does whatever the papers printed.
const seenHealth = x => x.condition && (x.condition.announced || x.condition.kind === 'wound' || x.condition.severity >= 3) ? `, ${healthText(x)}` : '';

// How a regiment stands toward the government, as its officers would put it to the staff: a temper, not a figure.
const faithWord = v => v >= 70 ? 'loyal' : v >= 52 ? 'steady' : v >= 35 ? 'wavering' : 'has lost faith in the government';
// The peoples and faiths of a province, as the census and the ethnographic maps of the age print them.
