  const fields = FIELDS.map(g => [g, ps.filter(p => p.deposits?.[g]?.known)]).filter(([, l]) => l.length).map(([g, l]) => `${GOOD_LABEL[g]} at ${few(l.map(p => `${p.name}${p.deposits[g].mine > 0 ? '' : ' (not worked)'}`))}`);
