  return `Known fields: ${fields.join('; ') || 'none of note'}. Works of note: ${works.join('; ') || 'none'}.${over.length ? ` It turns out more than it uses of ${over.join(', ')}.` : ''}${short.length ? ` It is short of ${short.join(', ')}.` : ''}`;
