  return `From the yearbooks:\n${money}\n${politics}\n${offices}\n${peoples} ${law}\n${papers}\n${recordOf(o)}\nWhat it holds, by the atlas and the mining returns: ${holdsLine(w, o)}\nWhat it leans on others for, and who leans on it (from the trade returns, the shipping lists and the treasuries' accounts): ${leanLines(w, o).join(' ')}\n${lifelines(w, c, o).split('\nHow a trade is cut.')[0]}${staff}`;
