  const called = live.map(o => [o, sumOf(Object.values(w.units).filter(u => u.country === o.id).map(u => u.called ? u.men : Math.min(u.calledMen || 0, u.men)))]).filter(([, n]) => n >= 5);
  if (called.length) out.push(`Reservists under arms: ${called.map(([o, n]) => `${o.name} about ${Math.round(n / 5) * 5} thousand${(o.calledUpAt ?? -9) >= since ? ' (called since you last looked)' : ''}`).join('; ')}.`);
  const signed = (w.treaties || []).filter(t => t.active && !t.secret && (t.since ?? -9) >= since);
  if (signed.length) out.push(`Signed since you last looked: ${signed.map(t => `${t.kind.replace(/_/g, ' ')} between ${t.parties.map(nm).join(' and ')}${t.cede?.length ? ` (${t.cede.map(p => w.provinces[p]?.name ?? p).join(', ')} changes hands)` : ''}`).join('; ')}.`);
  const broke = live.filter(o => o.defaulted); if (broke.length) out.push(`${broke.map(o => o.name).join(' and ')} ${broke.length > 1 ? 'have' : 'has'} stopped paying ${broke.length > 1 ? 'their' : 'its'} creditors.`);
