  if (moved.length) out.push(`On the exchanges, against a year ago: ${moved.map(([g, r]) => `${GOOD_LABEL[g]} ${r > 0 ? 'up' : 'down'} ${Math.round(Math.abs(r) * 100)} in the hundred`).join(', ')}.`);
