  const rules = ch.status === 'free' && governs(w, c, ch), seat = inOffice(w, ch) ? ch.role : rules ? 'leader' : null;
  const ls = t => String(answer(w, ch, t)).split('\n').filter(Boolean), until = (xs, re) => { const i = xs.findIndex(l => re.test(l)); return i < 0 ? xs : xs.slice(0, i); }, first = (xs, re) => xs.find(l => re.test(l)) ?? '', sentence = s => (s.match(/^.*?[^\d]\.(?=\s|$)/) ?? [s])[0];
  const out = [], put = (title, body) => { const text = (Array.isArray(body) ? body.filter(Boolean).join('\n') : body || '').trim(); if (text) out.push(`${title}\n${text}`); };
  const house = () => { if (!c.parliament) return []; const p = ls('parliament'), at = p.findIndex(l => l.startsWith('Pending bills:')), to = p.findIndex(l => l.startsWith('Recent decisions:')); return [p[0].split('; a motion of no confidence')[0] + '.', ...(at >= 0 ? p.slice(at, to > at ? to : at + 1).filter(l => !/^Pending bills: none/.test(l)) : [])]; };
  const vote = c.elections ? `The next election is due in ${quarterLabel(c.nextElection)}.` : '';
  const owed = ls('debts').filter(l => /\bowes? /.test(l)).slice(0, 6), deals = ls('contracts').filter(l => /^[A-Z]+\d+ /.test(l)).slice(0, 8);
  const papers = ls('press').filter(l => l.includes(`owned by ${ch.name}`));
  if (rules) {
    for (const [title, lines] of memoranda(w, c, ch)) put(title, lines);
    put('The treasury:', ls('budget').slice(0, 2));
    put('Money and the war:', warMoney(w, c));
    put('Treaties and pledges:', bondsText(w, c, ch));
    put('The forces:', [sentence(first(ls('army'), /^The military budget (covers|provides)/)), (c.arrears || 0) > .5 ? 'Pay is in arrears.' : '']);
    put('The country:', [(first(ls('blocs'), /Legitimacy/).match(/Legitimacy[^.]*\./) ?? [''])[0], ...ls('unrest').filter(l => /^P\d+ /.test(l)).slice(0, 2).map(l => `Most restless: ${l}`)]);
    put('The house and the vote:', [...house(), vote]);
  }
  if (seat === 'general' || rules) {
    const army = ls('army');
    put(seat === 'general' ? 'The army list:' : 'The army list (the chief of staff has the same before him):', until(army, /^Standing orders \(set_posture\)/));
    const ships = until(ls('fleet'), /^Our harbours:/).filter(l => /^G\d+ /.test(l)); put('The squadrons:', ships);
    if (seat === 'general') put('Treaties and pledges:', bondsText(w, c, ch));
    if (seat === 'general') put('Arsenal and pay:', [sentence(first(army, /^Ammunition:/)), sentence(first(army, /^The military budget (covers|provides)/))]);
    put('The frontiers:', ls('borders').filter(l => !/: nothing seen/.test(l)).map(l => l.startsWith('  What the staff sees') ? `  ${sentence(l.trim())}` : l));
  }
  if (seat === 'opposition') {
    put('Your party:', ls('parties').filter(l => /funds \d/.test(l)));
    put('The house and the vote:', [...house(), vote]);
    put('Your papers:', papers);
  }
  if (seat === 'oligarch') {
    put('Your works:', ls('my_companies').filter(l => /^[A-Z]+\d+ /.test(l)).slice(0, 14));
    put('Your papers:', papers);
    put('What the state takes from business:', `Tax on business ${Math.round(c.tax.business * 100)}%, general tariff ${Math.round(c.tariff * 100)}%.`);
  }
  // The state of the country, every morning: what a government's statistical office, its board of trade and its mint lay on the desk unasked,
  // and for the other seats what the papers and the exchange print of it. Each line is the answer the seat would have had to the lookup of
  // that name, no more and no less: what an office does not show a seat it does not show it here. (The owner, after eleven quarters in which
  // eight rulers asked for the economy three times, for the stores three times and for their trade once: "every morning they need a briefing:
  // the country's output, prices, production and use, its budgets, its trade and its resources, and in short what goes on in the world".)
  if (seat) {
    const eco = ls('economy'), bud = rules ? ls('budget') : [], fields = rules ? ls('resources').filter(l => /^P\d+ /.test(l)) : [];
    put('The state of the country, as it stood when the quarter closed:', [
      ...(seat === 'general' ? [sentence(eco[0] ?? '')] : eco),
      first(bud, /^Where last quarter's revenue came from/), first(bud, /^Where it went/),
      rules || seat === 'oligarch' || seat === 'general' ? (ls('stocks')[0] ?? '').split(' With every works running flat out')[0] : '',
      ...(rules || seat === 'oligarch' || seat === 'opposition' ? ls('trade').slice(0, 2) : []),
      ...(rules || seat === 'oligarch' ? ls('market').slice(0, 2) : []),
      fields.length ? `The country's known fields: ${fields.join('; ')}.` : '',
      ...(rules || seat === 'opposition' ? ls('mood').filter(l => /\(content (about )?\d+ of 100\)/.test(l)) : []),
      rules ? first(ls('population'), /^About \d/) : '',
    ]);
  }
  put('The world this morning:', worldToday(w, c, ch));
  if (rules || seat === 'oligarch' || seat === 'opposition') put('The markets and the wars:', marketsAndWars(w, c));
  if (rules || seat === 'oligarch') put('Whom the country leans on, and who leans on it:', leanLines(w, c, true));
  if (rules || seat === 'oligarch') put('How the country\'s trade travels, by the consuls\' returns:', tradeWays(w, c));
  // What stands until it is changed is laid out as that, so that no morning is spent giving the same orders again. (World 16: of 553 orders of
  // posture 378 ordered what already stood, and a third of the rulings that were only words said "everything stays as it is".)
